import{_ as a,o,c as t,a7 as r}from"./chunks/framework.FWlv_suP.js";const m=JSON.parse('{"title":"Who Called Support","description":"Official support information for Who Called.","frontmatter":{"title":"Who Called Support","description":"Official support information for Who Called.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"support/who-called.md","filePath":"support/who-called.md"}'),i={name:"support/who-called.md"};function n(l,e,s,d,p,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="who-called-support" tabindex="-1">Who Called Support <a class="header-anchor" href="#who-called-support" aria-label="Permalink to &quot;Who Called Support&quot;">​</a></h1><p>For Who Called support, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p><p>Include the app version, Android or browser version, device model, a description of the issue, and safe reproduction steps. Do not email PINs, private contacts, saved messages, call logs, or backup files.</p><h2 id="common-help" tabindex="-1">Common help <a class="header-anchor" href="#common-help" aria-label="Permalink to &quot;Common help&quot;">​</a></h2><ul><li><strong>Call history unavailable:</strong> use an Android build that includes the feature, enable it in the app, and grant call-log permission. Distribution policy can require this feature to be omitted. Other features work without this permission.</li><li><strong>Forgotten PIN:</strong> the PIN is not recoverable. Clearing app storage or reinstalling also removes local data; preserve a usable backup beforehand.</li><li><strong>Biometric unlock unavailable:</strong> use the PIN and confirm Android has a supported enrolled biometric.</li><li><strong>Backup restore fails:</strong> select a <code>.contactvault</code> backup and enter the exact passphrase used when it was created.</li><li><strong>WhatsApp does not open:</strong> verify WhatsApp or WhatsApp Business is installed and check the complete international phone number.</li><li><strong>Contact import fails:</strong> choose a valid vCard or CSV file with required name and phone information.</li><li><strong>Reminder does not appear:</strong> reminders are available only in the Android app. Enable “Remind me,” grant notification permission, and confirm notifications are enabled for Who Called in Android settings. Battery optimization can delay the approximately 6:00 AM delivery time.</li><li><strong>Wrong birthday or anniversary reminder:</strong> edit the contact and verify its month, day, optional year, anniversary name, and reminder switch. The Alert Directory can disable individual reminders or all reminders for a contact.</li><li><strong>Detected link or phone number does not open:</strong> select the detected item in the full saved-message view and confirm the requested external action.</li></ul>',5)])])}const f=a(i,[["render",n]]);export{m as __pageData,f as default};
